int main() {
    int t; cin >> t;
    while (t--) {
        int n, x; cin >> n >> x;
        stack<int> st;
        for (int i = 0; i < n; i++) { int v; cin >> v; st.push(v); }  // bottom -> top
        stack<int> res = pushAtBottom(st, x);
        vector<int> out;
        while (!res.empty()) { out.push_back(res.top()); res.pop(); }
        cout << "bottom -> top:";
        for (int i = out.size() - 1; i >= 0; i--) cout << " " << out[i];
        cout << "\n";
    }
    return 0;
}

// reads a stack whose values are given from the top down
stack<int> readStack() {
    int n; cin >> n;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    stack<int> st;
    for (int i = n - 1; i >= 0; i--) st.push(v[i]);  // first value ends on top
    return st;
}
